import{describe,it,expect}from"vitest";import{parseIntent,INTENTS}from"../../frontend/js-modules/voice/intent-parser.js";describe("parseIntent",()=>{it("falls back to QA for empty input",()=>{expect(parseIntent("").intent).toBe(INTENTS.QA_FALLBACK)}),it("falls back to QA for an open-ended travel question",()=>{const t=parseIntent("What is the best time to visit Kerala?");expect(t.intent).toBe(INTENTS.QA_FALLBACK)}),it("recognizes a navigation command and resolves the route",()=>{const t=parseIntent("take me to the wildlife page");expect(t.intent).toBe(INTENTS.NAVIGATE),expect(t.slots.target.path).toBe("/frontend/wildlife/wildlife.html")}),it("recognizes a bookmark command",()=>{const t=parseIntent("bookmark this");expect(t.intent).toBe(INTENTS.BOOKMARK)}),it("recognizes a search command and extracts the query",()=>{const t=parseIntent("search for houseboats in Alleppey");expect(t.intent).toBe(INTENTS.SEARCH),expect(t.slots.query).toBe("houseboats in alleppey")}),it("recognizes an itinerary command with destination and day count",()=>{const t=parseIntent("plan a trip to Goa for 5 days");expect(t.intent).toBe(INTENTS.ITINERARY),expect(t.slots.days).toBe(5),expect(t.slots.destination).toContain("goa")}),it("recognizes a language switch command",()=>{const t=parseIntent("switch to Hindi");expect(t.intent).toBe(INTENTS.LANGUAGE_SWITCH),expect(t.slots.language).toEqual({name:"hindi",code:"hi"})}),it("is case-insensitive",()=>{const t=parseIntent("GO TO CULTURE");expect(t.intent).toBe(INTENTS.NAVIGATE),expect(t.slots.target.key).toBe("culture")})});